import { useEffect, useState } from 'react'
import Modal from './Modal.jsx'
import { useApp } from '../context/AppContext.jsx'
import { useModal } from '../context/ModalContext.jsx'
import { APPEL_CANAUX, APPEL_RESULTATS, APPEL_SENTIMENTS } from '../utils/constants.js'
import { nowISODateTime } from '../utils/formatters.js'

// Calls are normally generated by the AI agent itself — this form only
// exists to add a manual test entry (e.g. for demos).
const BLANK = {
  clientId: '',
  date: nowISODateTime(),
  duree: '',
  canal: 'téléphone',
  resultat: 'rdv_pris',
  resume: '',
  transcript: '',
  sentiment: 'neutre',
}

export default function AppelModal() {
  const { modal, closeModal } = useModal()
  const { clients, addAppel } = useApp()
  const isOpen = modal.type === 'appel'

  const [form, setForm] = useState(BLANK)
  const [errors, setErrors] = useState({})

  useEffect(() => {
    if (isOpen) {
      setForm({ ...BLANK, ...modal.initialData })
      setErrors({})
    }
  }, [isOpen, modal.initialData])

  function setField(field, value) {
    setForm((prev) => ({ ...prev, [field]: value }))
  }

  function handleSubmit(e) {
    e.preventDefault()
    const nextErrors = {}
    if (!form.clientId) nextErrors.clientId = 'Le cabinet client est requis.'
    if (!form.resume.trim()) nextErrors.resume = 'Un résumé est requis.'
    if (Object.keys(nextErrors).length) {
      setErrors(nextErrors)
      return
    }
    addAppel({ ...form, duree: Number(form.duree) || 0 })
    closeModal()
  }

  return (
    <Modal
      isOpen={isOpen}
      onClose={closeModal}
      title="Nouvel appel (test)"
      footer={
        <>
          <button type="button" className="btn btn-secondary" onClick={closeModal}>Annuler</button>
          <button type="submit" form="appel-form" className="btn btn-primary">Enregistrer</button>
        </>
      }
    >
      <form id="appel-form" onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 14 }}>
        <div className="form-field">
          <label className="form-label" htmlFor="ap-client">Cabinet client <span className="required">*</span></label>
          <select id="ap-client" className="form-control" value={form.clientId} onChange={(e) => setField('clientId', e.target.value)}>
            <option value="">— Sélectionner —</option>
            {clients.map((c) => <option key={c.id} value={c.id}>{c.nomCabinet} · {c.ville}</option>)}
          </select>
          {errors.clientId && <span className="form-error">{errors.clientId}</span>}
        </div>

        <div className="form-row">
          <div className="form-field">
            <label className="form-label" htmlFor="ap-date">Date et heure</label>
            <input id="ap-date" type="datetime-local" className="form-control" value={form.date} onChange={(e) => setField('date', e.target.value)} />
          </div>
          <div className="form-field">
            <label className="form-label" htmlFor="ap-duree">Durée (secondes)</label>
            <input id="ap-duree" type="number" min="0" className="form-control" value={form.duree} onChange={(e) => setField('duree', e.target.value)} />
          </div>
        </div>

        <div className="form-row">
          <div className="form-field">
            <label className="form-label" htmlFor="ap-canal">Canal</label>
            <select id="ap-canal" className="form-control" value={form.canal} onChange={(e) => setField('canal', e.target.value)}>
              {APPEL_CANAUX.map((c) => <option key={c.value} value={c.value}>{c.label}</option>)}
            </select>
          </div>
          <div className="form-field">
            <label className="form-label" htmlFor="ap-resultat">Résultat</label>
            <select id="ap-resultat" className="form-control" value={form.resultat} onChange={(e) => setField('resultat', e.target.value)}>
              {APPEL_RESULTATS.map((r) => <option key={r.value} value={r.value}>{r.label}</option>)}
            </select>
          </div>
        </div>

        <div className="form-field">
          <label className="form-label" htmlFor="ap-sentiment">Sentiment</label>
          <select id="ap-sentiment" className="form-control" value={form.sentiment} onChange={(e) => setField('sentiment', e.target.value)}>
            {APPEL_SENTIMENTS.map((s) => <option key={s.value} value={s.value}>{s.label}</option>)}
          </select>
        </div>

        <div className="form-field">
          <label className="form-label" htmlFor="ap-resume">Résumé <span className="required">*</span></label>
          <textarea id="ap-resume" className="form-control" value={form.resume} onChange={(e) => setField('resume', e.target.value)} />
          {errors.resume && <span className="form-error">{errors.resume}</span>}
        </div>

        <div className="form-field">
          <label className="form-label" htmlFor="ap-transcript">Transcript</label>
          <textarea id="ap-transcript" className="form-control" style={{ minHeight: 100 }} value={form.transcript} onChange={(e) => setField('transcript', e.target.value)} />
        </div>
      </form>
    </Modal>
  )
}
